"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import pb from "@/lib/pb";

type TournamentFormData = {
  name: string;
  category: string;
  description: string;
  rules: string;
  limit: string;
  startDate: string;
  endDate: string;
};

const CreateTournamentForm = () => {
  const [formData, setFormData] = useState<TournamentFormData>({
    name: "",
    category: "",
    description: "",
    rules: "",
    limit: "",
    startDate: "",
    endDate: "",
  });

  const [error, setError] = useState("");

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
  e.preventDefault();
  setError("");

  for (const key in formData) {
    if (!formData[key as keyof TournamentFormData]) {
      setError("Todos los campos son obligatorios");
      return;
    }
  }

  if (Number(formData.limit) <= 0) {
    setError("El límite debe ser mayor a 0");
    return;
  }

  const start = new Date(formData.startDate);
  const end = new Date(formData.endDate);

  if (end <= start) {
    setError("La fecha de fin no puede ser menor o igual a la de inicio");
    return;
  }

  try {
    const res = await fetch("app/api/crearTorneo", {
      method: "POST",
      body: JSON.stringify({
        ...formData,
        startDate: start.toISOString(),
        endDate: end.toISOString(),
      }),
      headers: {
        "Content-Type": "application/json",
      },
    });

    const json = await res.json();

    if (!json.ok) {
      setError(json.error);
      return;
    }

    alert("Torneo creado correctamente");

    setFormData({
      name: "",
      category: "",
      description: "",
      rules: "",
      limit: "",
      startDate: "",
      endDate: "",
    });

  } catch (err) {
    console.error(err);
    setError("Error inesperado");
  }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="space-y-4">

        <div>
          <Label>Nombre del Torneo</Label>
          <Input name="name" value={formData.name} onChange={handleChange} />
        </div>

        <div>
          <Label>Categoría</Label>
          <select
            name="category"
            value={formData.category}
            onChange={handleChange}
            className="w-full border rounded p-2"
          >
            <option value="">Seleccionar categoría</option>
            <option value="Deporte">Deporte</option>
            <option value="E-Sports">E-Sports</option>
            <option value="Estrategia">Estrategia</option>
          </select>
        </div>

        <div>
          <Label>Descripción</Label>
          <Textarea name="description" value={formData.description} onChange={handleChange} />
        </div>

        <div>
          <Label>Reglas</Label>
          <Textarea name="rules" value={formData.rules} onChange={handleChange} />
        </div>

        <div>
          <Label>Límite de Inscripciones</Label>
          <Input
            type="number"
            name="limit"
            value={formData.limit}
            onChange={handleChange}
          />
        </div>

        <div>
          <Label>Fecha de Inicio</Label>
          <Input
            type="datetime-local"
            name="startDate"
            value={formData.startDate}
            onChange={handleChange}
          />
        </div>

        <div>
          <Label>Fecha de Fin</Label>
          <Input
            type="datetime-local"
            name="endDate"
            value={formData.endDate}
            onChange={handleChange}
          />
        </div>

        {error && <p className="text-red-600">{error}</p>}

        <Button type="submit">
          Confirmar creación del torneo
        </Button>

      </div>
    </form>
  );
};

export default CreateTournamentForm;